const assert = require("node:assert/strict");
const test = require("node:test");
const { handle, countFor, failSend, deliveries } = require("./mailer");

test("ticket.opened duplicate delivery does not double-mail", () => {
  const event = {
    id: "evt_open_1",
    type: "ticket.opened",
    data: { ticketId: "t_open", to: "user@inkwell.test" },
  };
  handle(event);
  handle(event);
  assert.equal(countFor("ticket.opened"), 1);
});

test("failed send keeps the outbox row", () => {
  const event = {
    id: "evt_open_fail",
    type: "ticket.opened",
    data: { ticketId: "t_fail", to: "user@inkwell.test" },
  };
  handle(event);
  failSend(event.id);
  const row = deliveries().find((item) => item.eventId === event.id);
  assert.ok(row);
  assert.equal(row.status, "failed");
});

test("ticket.resolved is not routed yet", () => {
  const event = {
    id: "evt_res_pending",
    type: "ticket.resolved",
    data: { ticketId: "t_res", to: "user@inkwell.test" },
  };
  assert.equal(handle(event), null);
  assert.equal(countFor("ticket.resolved"), 0);
});

const { dispatchOnce, markFailed, deliveries } = require("./outbox");

function handle(event) {
  if (event.type === "ticket.opened") {
    return dispatchOnce(event.id, event.type, event.data);
  }
  return null;
}

function countFor(channel) {
  let n = 0;
  for (const row of deliveries()) {
    if (row.channel === channel) n += 1;
  }
  return n;
}

function failSend(eventId) {
  return markFailed(eventId);
}

module.exports = { handle, countFor, failSend, deliveries };

const sent = [];
const byKey = new Map();

function dispatchOnce(eventId, channel, body) {
  const hit = byKey.get(eventId);
  if (hit) return hit;
  const row = Object.freeze({
    seq: sent.length,
    eventId,
    channel,
    body,
    status: "sent",
  });
  sent.push(row);
  byKey.set(eventId, row);
  return row;
}

function sendDirect(channel, body) {
  const row = Object.freeze({
    seq: sent.length,
    eventId: null,
    channel,
    body,
    status: "sent",
  });
  sent.push(row);
  return row;
}

function markFailed(eventId) {
  const hit = byKey.get(eventId);
  if (!hit) return null;
  const row = Object.freeze({ ...hit, status: "failed" });
  sent[hit.seq] = row;
  byKey.set(eventId, row);
  return row;
}

function retryFailed() {
  const retried = [];
  for (const row of sent) {
    if (row.status !== "failed" || !row.eventId) continue;
    const next = Object.freeze({ ...row, status: "sent" });
    sent[row.seq] = next;
    byKey.set(row.eventId, next);
    retried.push(next);
  }
  return retried;
}

function deliveries() {
  return sent.slice();
}

module.exports = { dispatchOnce, sendDirect, markFailed, retryFailed, deliveries };

